  {
   "id": 15,
   "name": "Cunning Stunts",
   "description": "Complete 250 Stunts.",
   "grade": "silver",
   "hidden": false,
   "kind": ["activities", "collectibles"],
   "missable": false,
   "stage": 2,
   "guide": "Complete any 250 of the 397 stunts across Leonida (the 100% checklist wants 300). There are four kinds: 130 stunt jumps off ramps, 202 under-the-bridge flights, 40 knife flights between buildings and 25 base jumps. Mix them freely — under-the-bridge flights are the quickest. Track progress under Progress > Activities > Stunts, and find stunt spots on the map under Exploration > Stunt Spots; each one stays marked once done. Performing a stunt once counts — you do not need its extra challenge.",
   "source": "PowerPyx — GTA 6 Trophy Guide & Roadmap",
   "source_url": "https://www.powerpyx.com/gta-6-grand-theft-auto-vi-trophy-guide-roadmap/"
  },
